<?php
require __DIR__ . '/../app/bootstrap.php';
require_login();
$page = $_GET['page'] ?? 'dashboard';
$pages = ['dashboard','inquilinos','cargos','ingresos','fianzas','usuarios','backup'];
if (!in_array($page,$pages,true)) $page='dashboard';
$user=current_user(); $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();
 try {
  $a=$_POST['action']??'';
  if($a==='tenant_save'){
   $d=[trim($_POST['nombre']??''),trim($_POST['dni_nie']??''),trim($_POST['telefono']??''),trim($_POST['email']??''),trim($_POST['unidad']??''),($_POST['fecha_entrada']?:null),($_POST['fecha_salida']?:null),(float)($_POST['alquiler_mensual']??0),$_POST['estado']??'ACTIVO',trim($_POST['notas']??'')];
   if(!$d[0])throw new RuntimeException('El nombre es obligatorio.');
   $pdo->prepare('INSERT INTO inquilinos(nombre,dni_nie,telefono,email,unidad,fecha_entrada,fecha_salida,alquiler_mensual,estado,notas) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute($d);
   flash('Inquilino guardado.');header('Location: '.url('inquilinos'));exit;
  }
  if($a==='charge_save'){
   $pdo->prepare('INSERT INTO cargos(fecha,tipo,concepto,inquilino_id,importe,mes,pagado_por) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['fecha'],$_POST['tipo'],trim($_POST['concepto']),(int)$_POST['inquilino_id'],(float)$_POST['importe'],($_POST['mes']?:null),$_POST['pagado_por']]);flash('Cargo registrado.');header('Location: '.url('cargos'));exit;
  }
  if($a==='income_save'){
   $pdo->prepare('INSERT INTO ingresos(fecha,importe,concepto,inquilino_id,metodo) VALUES(?,?,?,?,?)')->execute([$_POST['fecha'],(float)$_POST['importe'],trim($_POST['concepto']),(int)$_POST['inquilino_id'],$_POST['metodo']]);flash('Ingreso registrado.');header('Location: '.url('ingresos'));exit;
  }
  if($a==='deposit_save'){
   $pdo->prepare('INSERT INTO fianzas(inquilino_id,fecha,pagada,a_devolver,resto,estado,motivo_retencion,importe_danos,detalle_retencion) VALUES(?,?,?,?,?,?,?,?,?)')->execute([(int)$_POST['inquilino_id'],$_POST['fecha'],(float)$_POST['pagada'],(float)$_POST['a_devolver'],(float)$_POST['resto'],$_POST['estado'],$_POST['motivo_retencion'],(float)$_POST['importe_danos'],trim($_POST['detalle_retencion'])]);flash('Fianza registrada.');header('Location: '.url('fianzas'));exit;
  }
  if($a==='user_save'){
   require_admin();$n=trim($_POST['nombre']);$em=trim($_POST['email']);$pw=$_POST['password']??'';$role=$_POST['rol']??'GESTOR';
   if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<12)throw new RuntimeException('Comprueba nombre, email y contraseña (mínimo 12 caracteres).');
   if(!in_array($role,['ADMIN','GESTOR','LECTURA'],true))throw new RuntimeException('Rol no válido.');
   $pdo->prepare('INSERT INTO usuarios(nombre,email,password_hash,rol,activo) VALUES(?,?,?,?,1)')->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT),$role]);flash('Usuario creado.');header('Location: '.url('usuarios'));exit;
  }
 } catch(Throwable $ex){$error=$ex instanceof PDOException?'No se pudo guardar. Comprueba los datos y que no exista un email duplicado.':$ex->getMessage();}
}
$names=$pdo->query('SELECT id,nombre FROM inquilinos ORDER BY nombre')->fetchAll();
$labels=['dashboard'=>'Resumen','inquilinos'=>'Inquilinos','cargos'=>'Cargos e ingresos','ingresos'=>'Ingresos','fianzas'=>'Fianzas y daños','usuarios'=>'Usuarios','backup'=>'Copias de seguridad'];
$stats=['t'=>(int)$pdo->query("SELECT COUNT(*) FROM inquilinos WHERE estado='ACTIVO'")->fetchColumn(),'c'=>(float)$pdo->query('SELECT COALESCE(SUM(importe),0) FROM cargos')->fetchColumn(),'i'=>(float)$pdo->query('SELECT COALESCE(SUM(importe),0) FROM ingresos')->fetchColumn(),'f'=>(float)$pdo->query('SELECT COALESCE(SUM(resto),0) FROM fianzas WHERE liquidada=0')->fetchColumn()];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($labels[$page])?> · APP Alquileres</title><link rel="stylesheet" href="assets/app.css"></head><body>
<header class="topbar"><a class="brand" href="<?=e(url())?>"><span class="brand-icon">⌂</span><span>APP Alquileres<small>Gestión de alquileres</small></span></a><div class="userbox"><span><?=e($user['nombre'])?> · <?=e($user['rol'])?></span><a class="btn outline" href="logout.php">Cerrar sesión</a></div></header>
<div class="layout"><nav class="sidebar"><?php foreach($labels as $k=>$v):?><a class="<?=$page===$k?'active':''?>" href="<?=e(url($k))?>"><?=e($v)?></a><?php endforeach;?></nav><main class="content"><div class="page-head"><div><h1><?=e($labels[$page])?></h1><p class="muted">Gestión centralizada de inquilinos, movimientos y fianzas.</p></div></div>
<?php if(!empty($_SESSION['flash'])):?><div class="notice"><?=e($_SESSION['flash'])?></div><?php unset($_SESSION['flash']);endif;?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?>
<?php if($page==='dashboard'):?>
<div class="kpis"><div class="kpi"><span>Inquilinos activos</span><strong><?=$stats['t']?></strong></div><div class="kpi"><span>Total cargos</span><strong><?=money($stats['c'])?></strong></div><div class="kpi"><span>Total ingresos</span><strong><?=money($stats['i'])?></strong></div><div class="kpi"><span>Fianzas pendientes</span><strong><?=money($stats['f'])?></strong></div></div><section class="panel"><h3>Accesos rápidos</h3><div class="actions"><a class="btn primary" href="<?=e(url('inquilinos'))?>">Añadir inquilino</a><a class="btn outline" href="<?=e(url('cargos'))?>">Registrar cargo</a><a class="btn outline" href="<?=e(url('ingresos'))?>">Registrar ingreso</a></div></section>
<?php elseif($page==='inquilinos'):?>
<section class="panel"><h3>Nuevo inquilino</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="tenant_save"><div><label>Nombre *</label><input name="nombre" required></div><div><label>DNI/NIE</label><input name="dni_nie"></div><div><label>Teléfono</label><input name="telefono"></div><div><label>Email</label><input type="email" name="email"></div><div><label>Vivienda/unidad</label><input name="unidad"></div><div><label>Alquiler mensual (€)</label><input type="number" min="0" step=".01" name="alquiler_mensual" value="0"></div><div><label>Fecha entrada</label><input type="date" name="fecha_entrada"></div><div><label>Fecha salida</label><input type="date" name="fecha_salida"></div><div><label>Estado</label><select name="estado"><option>ACTIVO</option><option>INACTIVO</option></select></div><div class="full"><label>Notas</label><textarea name="notas"></textarea></div><div class="full"><button class="btn primary">Guardar inquilino</button></div></form></section><section class="panel"><h3>Inquilinos registrados</h3><div class="table-wrap"><table><tr><th>Nombre</th><th>Unidad</th><th>Contacto</th><th>Alquiler</th><th>Estado</th></tr><?php foreach($pdo->query('SELECT * FROM inquilinos ORDER BY nombre') as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['unidad'])?></td><td><?=e($r['telefono'])?><br><?=e($r['email'])?></td><td><?=money($r['alquiler_mensual'])?></td><td><?=e($r['estado'])?></td></tr><?php endforeach;?></table></div></section>
<?php elseif(in_array($page,['cargos','ingresos','fianzas'],true)):?>
<section class="panel"><h3>Nuevo registro</h3><?php if(!$names):?><p>Primero crea un inquilino.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$page==='cargos'?'charge_save':($page==='ingresos'?'income_save':'deposit_save')?>"><div><label>Inquilino</label><select name="inquilino_id" required><?php foreach($names as $n):?><option value="<?=$n['id']?>"><?=e($n['nombre'])?></option><?php endforeach;?></select></div><div><label>Fecha</label><input type="date" name="fecha" value="<?=date('Y-m-d')?>" required></div><?php if($page==='cargos'):?><div><label>Tipo</label><select name="tipo"><?php foreach(['Alquiler','Basura','Luz','Agua','Internet','Electricidad','Reparacion','Otros'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div><div><label>Mes (AAAA-MM)</label><input name="mes" placeholder="<?=date('Y-m')?>"></div><div><label>Pagado por</label><select name="pagado_por"><option>Propietario</option><option>Inquilino</option><option>Otro</option></select></div><?php endif;?><?php if($page==='ingresos'):?><div><label>Método</label><select name="metodo"><?php foreach(['Transferencia','Bizum','Efectivo','Otro'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div><?php endif;?><?php if($page==='fianzas'):?><div><label>Estado</label><select name="estado"><?php foreach(['RETENIDA','DEVUELTA','PARCIAL','LIQUIDADA'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div><div><label>Motivo</label><select name="motivo_retencion"><?php foreach(['Ninguno','Deuda','Daños','Limpieza','Mixto'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div><div><label>Importe a devolver (€)</label><input type="number" name="a_devolver" min="0" step=".01" value="0"></div><div><label>Resto pendiente (€)</label><input type="number" name="resto" min="0" step=".01" value="0"></div><div><label>Importe daños (€)</label><input type="number" name="importe_danos" min="0" step=".01" value="0"></div><div class="full"><label>Detalle de retención</label><textarea name="detalle_retencion"></textarea></div><?php endif;?><div><label>Importe (€)</label><input type="number" name="<?=$page==='fianzas'?'pagada':'importe'?>" min="0" step=".01" required></div><div class="full"><label>Concepto</label><input name="concepto" required></div><div class="full"><button class="btn primary">Guardar</button></div></form><?php endif;?></section>
<section class="panel"><h3>Últimos movimientos</h3><div class="table-wrap"><table><tr><th>Fecha</th><th>Inquilino</th><th>Concepto</th><th>Importe</th><th>Tipo/estado</th></tr><?php $tab=$page==='cargos'?'cargos':$page;$rows=$pdo->query("SELECT x.*,i.nombre FROM $tab x JOIN inquilinos i ON i.id=x.inquilino_id ORDER BY x.fecha DESC,x.id DESC LIMIT 100")->fetchAll();foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['nombre'])?></td><td><?=e($r['concepto']??$r['motivo_retencion']??'Fianza')?></td><td><?=money($r['importe']??$r['pagada']??0)?></td><td><?=e($r['tipo']??$r['estado']??'')?></td></tr><?php endforeach;?></table></div></section>
<?php elseif($page==='usuarios'):?><?php if($user['rol']!=='ADMIN'):?><div class="notice error">Solo el administrador puede gestionar usuarios.</div><?php else:?><section class="panel"><h3>Crear usuario</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_save"><div><label>Nombre</label><input name="nombre" required></div><div><label>Email</label><input type="email" name="email" required></div><div><label>Contraseña (mínimo 12 caracteres)</label><input type="password" name="password" minlength="12" required></div><div><label>Rol</label><select name="rol"><option>GESTOR</option><option>LECTURA</option><option>ADMIN</option></select></div><div class="full"><button class="btn primary">Crear usuario</button></div></form></section><section class="panel"><h3>Usuarios existentes</h3><div class="table-wrap"><table><tr><th>Nombre</th><th>Email</th><th>Rol</th><th>Activo</th></tr><?php foreach($pdo->query('SELECT nombre,email,rol,activo FROM usuarios ORDER BY nombre') as $u):?><tr><td><?=e($u['nombre'])?></td><td><?=e($u['email'])?></td><td><?=e($u['rol'])?></td><td><?=$u['activo']?'Sí':'No'?></td></tr><?php endforeach;?></table></div></section><?php endif;?>
<?php elseif($page==='backup'):?><section class="panel"><h3>Copias de seguridad</h3><p>Por ahora, utiliza phpMyAdmin: selecciona <code>app_alquileres</code>, pulsa Exportar y elige SQL. Guarda la copia fuera del servidor. La restauración guiada queda pendiente.</p><a class="btn outline" href="http://localhost/phpmyadmin/" target="_blank" rel="noopener">Abrir phpMyAdmin</a></section><?php endif;?>
<footer>APP Alquileres · Base inicial de desarrollo</footer></main></div></body></html>
